using Cineclay.Shared;
var count=0;
void Check(bool ok,string name){if(!ok)throw new Exception(name);count++;}
Movie Film()=>new(){Id=1,Title="Test",Summary="Synopsis",Year=1990,Genres=["Drama"],Cast=["Actor","Actress"]};
var m=Film();Check(m.Validate()==null,"Valid movie");m.Year=1989;Check(m.Validate()!=null,"Reject pre-1990");m.Year=2099;Check(m.Validate()==null,"Accept future year");m.Poster="javascript:alert(1)";Check(m.Validate()!=null,"Reject unsafe poster scheme");m.Poster="http://example.com/a.jpg";Check(m.Validate()!=null,"Require HTTPS");m.Poster="/posters/dune.jpg";Check(m.Validate()==null,"Allow bundled artwork");m.Trailer="../../unsafe";Check(m.Validate()!=null,"Reject unsafe trailer ID");m.Trailer="Way9Dexny3w";Check(m.Validate()==null,"Allow video ID");m.Providers.Add(new(){Name="Example",Url="https://example.com/title/1",Region="IN"});Check(m.Validate()==null,"Allow direct OTT link");m.Providers[0].Region="India";Check(m.Validate()!=null,"Validate country code");m.Providers[0].Region="IN";m.Providers[0].Url="https://user:pass@example.com";Check(m.Validate()!=null,"Reject credentials in URLs");m=Film();m.Cast=[""];Check(m.Validate()!=null,"Reject empty cast names");m=Film();m.MediaType="tv";m.Providers=[new(){Name="Netflix",Region="GLOBAL",Type="official-title",Url="https://www.netflix.com/title/81231974"}];Check(m.Validate()==null,"Global official title page accepted");m.Providers[0].Type="subscription";Check(m.Validate()!=null,"Global link must not claim regional subscription availability");m=Film();m.MediaType="episode";Check(m.Validate()!=null,"Unsupported media type rejected");m=Film();m.Languages=["Hindi","Tamil"];Check(m.Validate()==null,"Multiple language tags accepted");m.Languages=[""];Check(m.Validate()!=null,"Blank language tag rejected");Console.WriteLine($"{count} model and URL validation checks passed.");
